  box(T('ARCHIVE A / M-27','档案A／M-27'),T('Catalog name: Wind Listener. Type: a fictional paper exhibit in the Museum of Curious Objects.','登记名称：听风器。类型：奇珍博物馆故事里的纸质展品。')),
  box(T('ARCHIVE B / M-72','档案B／M-72'),T('Catalog name: Wind Listener. Display story: visitors imagine the breeze carrying their wishes out through the paper model.','登记名称：听风器。展览故事：观众想象微风把自己的心愿从纸模型里带出去。')),
  box(T('ARCHIVE C / M-27','档案C／M-27'),T('Display story: visitors imagine a breeze passing over the top, circling the dial and reaching the marked base. The flat paper model does not make sound or need power.','展览故事：观众想象微风掠过顶部、绕过刻度盘，再到达带标记的底座。平面纸模型不发声，不需要电力。')),
