 P(T('Fixed-seat tasks / 2–4 pupils','固定座位任务／2至4人'),T('Read across the same row. Reg=Registrar, Build=Display Builder, Write=Recorder, Check=Evidence Checker. M3 numbers mean slip holders.','同一行向右看。登记、布置、记录、核查对应玩家第2页；第三关数字表示持卡编号。'),text(T('2 pupils: share 1 + 2 slips one at a time.','2人：分别持1张与2张，逐张分享。')),team(2),text(T('3 pupils: each holds one slip; join building/checking after sharing.','3人：各持一卡，分享后一起布置或核查。')),team(3),text(T('4 pupils: three holders and one builder/checker.','4人：三名持卡者，一名布置兼核查。')),team(4)),
